  let held=RetainedCloneGrant{maximum_items:usize::try_from(pooled.items).map_err(|_|ValueError::invariant("original held item credit overflow"))?,maximum_copy_bytes:usize::try_from(pooled.copy_bytes).map_err(|_|ValueError::invariant("original held copy credit overflow"))?,maximum_capacity_bytes:usize::try_from(pooled.capacity_bytes).map_err(|_|ValueError::invariant("original held capacity credit overflow"))?,maximum_release_bytes:usize::try_from(pooled.release_bytes).map_err(|_|ValueError::invariant("original held release credit overflow"))?,maximum_depth:plan.quantum.maximum_depth};
