  let mut charged=semio_framework_job_return_budget::OriginalReturnEscrowAmounts{items:actual.copied_items as u64,copy_bytes:actual.copied_bytes as u64,capacity_bytes:actual.retained_capacity_bytes as u64,release_bytes:actual.released_bytes as u64,work:observed.checked_add(plan.control_work).ok_or_else(||ValueError::invariant("native scope CPU overflow"))?};
  let over=charged.items>pooled.items||charged.copy_bytes>pooled.copy_bytes||charged.capacity_bytes>pooled.capacity_bytes||charged.release_bytes>pooled.release_bytes||charged.work>pooled.work;
  if over{charged=semio_framework_job_return_budget::OriginalReturnEscrowAmounts{items:charged.items.min(pooled.items),copy_bytes:charged.copy_bytes.min(pooled.copy_bytes),capacity_bytes:charged.capacity_bytes.min(pooled.capacity_bytes),release_bytes:charged.release_bytes.min(pooled.release_bytes),work:charged.work.min(pooled.work)};if let Some(outcome)=out.as_mut(){outcome.source_refusal.get_or_insert_with(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"native scope spent more than its quoted Source stock").with_retained_progress(actual));}}
